#[test]
fn fft_errors() {
    check(&[
        (
            r"@PLAIN8 FFT",
            Err(r"FFT can only be applied to bucketized Geo Time Series."),
        ),
        (
            r"@PLAIN8 FFTAP",
            Err(r"FFT can only be applied to bucketized Geo Time Series."),
        ),
        (
            r"@STR FFT",
            Err(r"FFT can only be applied to numeric Geo Time Series."),
        ),
        (
            r"@E8 FFT",
            Err(r"FFT can only be applied to numeric Geo Time Series."),
        ),
        (
            r"NEWGTS FFT",
            Err(r"FFT can only be applied to numeric Geo Time Series."),
        ),
        (
            r"NEWGTS FFTAP",
            Err(r"FFT can only be applied to numeric Geo Time Series."),
        ),
        (
            r"@GAP FFT",
            Err(r"Found a displaced tick, should have been 'bucketspan' away from previous."),
        ),
        (
            r"@GAP FFTAP",
            Err(r"Found a displaced tick, should have been 'bucketspan' away from previous."),
        ),
        (
            r"@F8 0 NaN NaN NaN 5.0 ADDVALUE FFT",
            Err(r"Found duplicate tick."),
        ),
        (
            r"@F8 5 NaN NaN NaN 1.0 ADDVALUE FFT",
            Err(r"Found a tick not on a bucket boundary."),
        ),
        (
            r"@F8 5 NaN NaN NaN 1.0 ADDVALUE FFTAP",
            Err(r"Found a tick not on a bucket boundary."),
        ),
        (
            r"@F8 80 NaN NaN NaN 1.0 ADDVALUE FFT",
            Ok(
                r#"[[{"c":"x","l":{"l":"v"},"a":{},"la":0,"v":[[0,-5.515000000000002],[1,1.8049550059248292],[2,4.828588315194382],[3,18.2585],[4,-1.8935433211192123],[5,-1.8935433211192116],[6,18.2585],[7,4.828588315194383],[8,1.8049550059248303]]},{"c":"x","l":{"l":"v"},"a":{},"la":0,"v":[[0,0.0],[1,4.316766035941631],[2,3.3925661811837196],[3,4.412399432281716],[4,7.161013314973607],[5,-7.161013314973609],[6,-4.412399432281716],[7,-3.3925661811837187],[8,-4.3167660359416296]]},11111.111111111111]]"#,
            ),
        ),
        (
            r"@F8 100 NaN NaN NaN 1.0 ADDVALUE FFT",
            Err(r"Found a displaced tick, should have been 'bucketspan' away from previous."),
        ),
        (r"FFT", Err(r"Empty stack.")),
        (r"FFTAP", Err(r"Empty stack.")),
        (
            r"1 FFT",
            Err(r"FFT can only operate on Geo Time Series instances."),
        ),
        (
            r"'a' FFT",
            Err(r"FFT can only operate on Geo Time Series instances."),
        ),
        (
            r"[ 1 ] FFT",
            Err(r"FFT can only operate on Geo Time Series instances."),
        ),
        (
            r"[ @F8 1 ] FFT",
            Err(r"FFT can only operate on Geo Time Series instances."),
        ),
        (
            r"[ @F8 @PLAIN8 ] FFT",
            Err(r"FFT can only be applied to bucketized Geo Time Series."),
        ),
        (
            r"{ 'a' @F8 } FFT",
            Err(r"FFT can only operate on Geo Time Series instances."),
        ),
        (
            r"NULL FFT",
            Err(r"FFT can only operate on Geo Time Series instances."),
        ),
        (r"IFFT", Err(r"Empty stack.")),
        (r"@I8 IFFT", Err(r"Empty stack.")),
        (
            r"1 @I8 IFFT",
            Err(r"IFFT expects a Geo Time Series of real parts below the imaginary parts GTS."),
        ),
        (
            r"@I8 1 IFFT",
            Err(r"IFFT expects a Geo Time Series of imaginary parts on top of the stack."),
        ),
        (
            r"@I8 @I3 IFFT",
            Err(r"Real and imaginary Geo Time Series MUST have the same number of values."),
        ),
        (
            r"@I3 @I8 IFFT",
            Err(r"Real and imaginary Geo Time Series MUST have the same number of values."),
        ),
        (
            r"@I8 @L8 IFFT",
            Err(r"IFFT real and imaginary parts GTS MUST be of type DOUBLE."),
        ),
        (
            r"@L8 @I8 IFFT",
            Err(r"IFFT real and imaginary parts GTS MUST be of type DOUBLE."),
        ),
        (
            r"@I8 @S8 IFFT",
            Err(r"IFFT real and imaginary parts GTS MUST be of type DOUBLE."),
        ),
        (
            r"@S8 @I8 IFFT",
            Err(r"IFFT real and imaginary parts GTS MUST be of type DOUBLE."),
        ),
        (
            r"@E8 @E8 IFFT",
            Err(r"IFFT real and imaginary parts GTS MUST be of type DOUBLE."),
        ),
        (
            r"[ @I8 @J8 ] IFFT",
            Err(r"IFFT expects a Geo Time Series of imaginary parts on top of the stack."),
        ),
        (
            r"@I8 NULL IFFT",
            Err(r"IFFT expects a Geo Time Series of imaginary parts on top of the stack."),
        ),
        (
            r"NULL @I8 IFFT",
            Err(r"IFFT expects a Geo Time Series of real parts below the imaginary parts GTS."),
        ),
        (
            r"@I8 'a' IFFT",
            Err(r"IFFT expects a Geo Time Series of imaginary parts on top of the stack."),
        ),
        (
            r"'a' @I8 IFFT",
            Err(r"IFFT expects a Geo Time Series of real parts below the imaginary parts GTS."),
        ),
        (
            r"NEWGTS NEWGTS IFFT",
            Err(r"IFFT real and imaginary parts GTS MUST be of type DOUBLE."),
        ),
        (
            r"@I8 NEWGTS IFFT",
            Err(r"IFFT real and imaginary parts GTS MUST be of type DOUBLE."),
        ),
    ]);
}

